import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0016 — Bookmarks, workspaces e page preview: dettagli","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0016-bookmarks-workspaces-preview-details.md","filePath":"adr/0016-bookmarks-workspaces-preview-details.md"}'),n={name:"adr/0016-bookmarks-workspaces-preview-details.md"};function r(s,e,c,d,l,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0016-—-bookmarks-workspaces-e-page-preview-dettagli" tabindex="-1">ADR-0016 — Bookmarks, workspaces e page preview: dettagli <a class="header-anchor" href="#adr-0016-—-bookmarks-workspaces-e-page-preview-dettagli" aria-label="Permalink to &quot;ADR-0016 — Bookmarks, workspaces e page preview: dettagli&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §3.4.6 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (Workspaces, Bookmarks, Page preview), §3.4.2 e §3.4.6 (scope di sync di <code>.memobrain/</code>)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no (lo spec e <code>shared/go/pathrules</code> concordano; vedi &quot;Scope di sync&quot;)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>M6-WP3 (seconda metà) aggiunge segnalibri, layout salvati e anteprima al passaggio sui link. Tutto vive nel frontend: i file passano da <code>VaultAPI.ReadConfig/WriteConfig</code>, la cui allow-list contiene già <code>bookmarks.json</code> e <code>workspaces.json</code> (nessuna modifica Go).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong><code>.memobrain/bookmarks.json</code></strong> — <code>{ &quot;version&quot;: 1, &quot;items&quot;: [...] }</code>, forma già diffusa (<code>file</code>, <code>folder</code>, <code>search</code>, <code>graph</code>, <code>group</code>). <code>file</code>: <code>path</code> e <code>subpath</code> (<code>#Titolo</code> oppure <code>#^id</code>); <code>search</code>: <code>query</code>; <code>graph</code>: <code>title</code> e <code>options</code> (oggetto opaco); <code>group</code>: <code>title</code> e <code>items</code> annidati. Campi e tipi sconosciuti sono conservati in scrittura; elementi malformati di tipo noto sono scartati. Gli elementi non hanno id: si indirizzano per percorso di indici. Rename/spostamento aggiornano i percorsi (hook additivo in <code>renameEntry</code>); la cancellazione non rimuove il segnalibro, che viene mostrato come mancante (il cestino è recuperabile e un sync può riportare il file). Il file viene riletto quando il watcher segnala una modifica esterna; le scritture proprie sono riconosciute e ignorate.</p><p><strong><code>.memobrain/workspaces.json</code></strong> — <code>{ &quot;version&quot;: 1, &quot;workspaces&quot;: [{ name, savedAt, layout, left, right }] }</code>, dove <code>layout</code> ha la forma di <code>workspace.json</code> (<code>parseLayout</code>) e <code>left</code>/<code>right</code> sono <code>{open, tab, width}</code>. Il nome è univoco senza distinguere maiuscole; salvare con un nome esistente sovrascrive dopo conferma. Il caricamento fa prima il flush di tutte le note aperte (registro <code>workspaces/flush.ts</code>, agganciato a <code>useNoteDocument</code>), poi scarta i tab con file inesistenti.</p><p><strong>Scope di sync.</strong> <code>workspaces.json</code> è locale al dispositivo: §3.4.6 lo dichiara &quot;No&quot; e <code>pathrules.IsExcluded</code> esclude ogni <code>.memobrain/workspace*.json</code> (il prefisso copre anche <code>workspaces.json</code>). <code>bookmarks.json</code> non è escluso da <code>pathrules</code>, quindi viene sincronizzato come impostazione utente; la tabella §3.4.6 non lo elenca esplicitamente: suggerito aggiungerlo alla riga &quot;per utente&quot;.</p><p><strong>Vault di sola lettura (mount viewer):</strong> segnalibri e workspace si leggono e si aprono, ma le modifiche sono disabilitate (comandi e menu nascosti o non attivi), non tenute in memoria.</p><p><strong>Hook del grafo.</strong> <code>bookmarks/graphHook.ts</code>: <code>registerGraphBookmarks({ open(options), capture?() })</code>. Il modulo grafo si registra una volta; senza registrazione un segnalibro <code>graph</code> mostra un avviso e &quot;Bookmark current graph&quot; è disabilitato. <code>options</code> non è mai interpretato dai segnalibri.</p><p><strong>Page preview.</strong> Estensione CodeMirror (<code>mousemove</code> + <code>posAtCoords</code>, riconosce <code>[[…]]</code> nel testo, quindi vale in Live Preview e Source) e handler sulla reading view. Con Cmd/Ctrl premuto (o sempre, impostazione <code>pagePreviewAlways</code>; disattivabile con <code>pagePreview</code>, in <code>editor.json</code>) e dopo 350 ms mostra un popover <code>position: fixed</code> (nessun layout shift, max 340 px con scroll) con il rendering di <code>renderMarkdown</code> (sezione per <code>#Titolo</code>, blocco per <code>#^id</code>). Chiusura: uscita del puntatore, Esc, click fuori, scroll, digitazione. Alternativa da tastiera: comando &quot;Preview link under cursor&quot; (anche su un link a fuoco nella reading view), che sposta il fuoco nel popover. Sicurezza: HTML già sanificato (DOMPurify), in più rimozione di ogni <code>src</code> non <code>blob:</code>/<code>data:image</code>, niente <code>style</code>; gli embed sono idratati con un solo livello; il popover non ha hover, quindi nessuna anteprima annidata; i link esterni passano da <code>openExternal</code>/<code>isSafeExternalUrl</code>.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Preview solo sui nodi <code>.cm-wikilink</code></strong> — scartata: non funziona in Source e con il link attivo.</li><li><strong>Rimuovere i segnalibri dei file cancellati</strong> — scartata: perdita silenziosa in caso di cancellazione esterna o sync parziale.</li><li><strong>Id persistiti per elemento</strong> — scartata: si discosta dalla forma diffusa del file senza benefici.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Un file di segnalibri modificato su due dispositivi segue la risoluzione di sync dei file non <code>.md</code> (copia di conflitto). La sidebar sinistra ha un tab in più (<code>bookmarks</code>); i workspace salvati con tab sconosciuti restano caricabili (il tab non viene validato).</p>',15)])])}const m=o(n,[["render",r]]);export{g as __pageData,m as default};
